function brand8(string $cat):string{$x=mb_strtolower($cat);if(str_contains($x,'control4')||str_contains($x,'c4'))return 'Control4';if(str_contains($x,'shelly'))return 'Shelly';if(str_contains($x,'lifesmart')||str_contains($x,'domot'))return 'LifeSmart';return 'Otro';}
function replaceCharge8(PDO $db,int $projectId,int $newChargeId,array $types):void{$m=implode(',',array_fill(0,count($types),'?'));$s=$db->prepare("SELECT id FROM charges WHERE project_id=? AND active=1 AND id<>? AND type IN ($m)");$s->execute(array_merge([$projectId,$newChargeId],$types));foreach($s as $old){$als=$db->prepare('SELECT payment_id,amount FROM allocations WHERE charge_id=?');$als->execute([$old['id']]);foreach($als as $al)$db->prepare('INSERT INTO allocations(payment_id,charge_id,amount) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=amount+VALUES(amount)')->execute([$al['payment_id'],$newChargeId,$al['amount']]);$db->prepare('DELETE FROM allocations WHERE charge_id=?')->execute([$old['id']]);$db->prepare('UPDATE charges SET active=0 WHERE id=?')->execute([$old['id']]);}}
