  if($a==='update_quote'){if(!$qid)throw new Exception('Presupuesto inválido.');$db->prepare('UPDATE quotes SET project_id=?,version_no=?,quote_category=?,currency="USD",quote_date=?,quote_families=?,quote_template_family=?,price_list_id=?,materials_amount=?,labor_amount=?,labor_description=?,subtotal=?,tax_mode="sin_iva",vat_rate=21,materials_tax_mode=?,materials_vat_rate=?,labor_tax_mode="sin_iva",labor_vat_rate=21,total=?,status=?,notes=? WHERE id=?')->execute([$pid,$version,$category,$date,implode(',',$families),$template,$listId,$materials,$labor,$laborDesc,$materials+$labor,$matMode,$matVat,$total,$status,$notes,$qid]);$db->prepare('DELETE FROM quote_items WHERE quote_id=?')->execute([$qid]);$db->prepare('DELETE FROM quote_labor_items WHERE quote_id=?')->execute([$qid]);}
  else{$db->prepare('INSERT INTO quotes(project_id,version_no,quote_category,currency,quote_date,quote_families,quote_template_family,price_list_id,materials_amount,labor_amount,labor_description,subtotal,tax_mode,vat_rate,materials_tax_mode,materials_vat_rate,labor_tax_mode,labor_vat_rate,total,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$pid,$version,$category,'USD',$date,implode(',',$families),$template,$listId,$materials,$labor,$laborDesc,$materials+$labor,'sin_iva',21,$matMode,$matVat,'sin_iva',21,$total,$status,$notes]);$qid=(int)$db->lastInsertId();}
  $ins=$db->prepare('INSERT INTO quote_items(quote_id,product_id,category,brand,section_title,block_order,sku,description,unit,quantity,unit_price,price_list_id,subtotal,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($items as $r)$ins->execute(array_merge([$qid],$r));
  $li=$db->prepare('INSERT INTO quote_labor_items(quote_id,title,description,amount,tax_mode,vat_rate,block_order) VALUES(?,?,?,?,?,?,?)');foreach($laborBlocks as $r)$li->execute(array_merge([$qid],$r));
  if($status==='aprobado_inicial'){$pct=(float)$project['engineering_pct'];$amt=round($total*$pct/100,2);$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'ingenieria','USD',?,?)")->execute([$pid,$qid,$date,'Adelanto de ingeniería '.$pct.'% · v'.$version,$amt]);$eng=(int)$db->lastInsertId();replaceCharge8($db,$pid,$eng,['ingenieria']);$db->prepare("UPDATE projects SET status='aprobado' WHERE id=?")->execute([$pid]);}
  if($status==='final'){$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'materiales','USD',?,?)")->execute([$pid,$qid,$date,'Materiales · presupuesto final v'.$version,$matTotal]);$mat=(int)$db->lastInsertId();replaceCharge8($db,$pid,$mat,['materiales']);if($labTotal>0){$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'mano_obra','USD',?,?)")->execute([$pid,$qid,$date,'Mano de obra · presupuesto final v'.$version,$labTotal]);$labId=(int)$db->lastInsertId();replaceCharge8($db,$pid,$labId,['ingenieria','mano_obra']);}$db->prepare("UPDATE projects SET status='en_obra' WHERE id=?")->execute([$pid]);}
  $db->commit();$_SESSION['msg']=$a==='update_quote'?'Presupuesto actualizado.':'Presupuesto creado.';go8('index.php?a=quote_view&id='.$qid);
 }catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$_SESSION['msg']='No se pudo guardar: '.$ex->getMessage();go8('index.php?a='.($a==='update_quote'?'edit_quote&id='.$qid:'new_quote'));}
}

$clients=$db->query("SELECT id,business_name FROM clients WHERE active=1 ORDER BY business_name")->fetchAll();$projects=$db->query("SELECT id,client_id,project_number,name FROM projects ORDER BY id DESC")->fetchAll();$lists=$db->query("SELECT id,name,markup_percentage FROM price_lists WHERE active=1 ORDER BY id")->fetchAll();$products=$db->query("SELECT p.id,p.sku,p.description,p.unit,p.cost_usd,COALESCE(pc.name,'Otros') category FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.active=1 ORDER BY p.sku")->fetchAll();
