if($editing){$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT q.*,p.client_id FROM quotes q JOIN projects p ON p.id=q.project_id WHERE q.id=?');$s->execute([$id]);$q=$s->fetch();if(!$q)exit('Presupuesto inexistente.');$preClient=(int)$q['client_id'];$s=$db->prepare('SELECT product_id,quantity,unit_price,section_title,block_order FROM quote_items WHERE quote_id=? ORDER BY block_order,sort_order,id');$s->execute([$id]);foreach($s as $it){$o=(int)$it['block_order'];if(!isset($blocks[$o]))$blocks[$o]=['type'=>'materials','title'=>$it['section_title']?:'Materiales','items'=>[],'order'=>$o];$blocks[$o]['items'][]=$it;}$s=$db->prepare('SELECT * FROM quote_labor_items WHERE quote_id=? ORDER BY block_order,id');$s->execute([$id]);foreach($s as $li)$blocks[(int)$li['block_order']]=['type'=>'labor','title'=>$li['title'],'description'=>$li['description'],'amount'=>(float)$li['amount'],'tax_mode'=>$li['tax_mode'],'vat_rate'=>(float)$li['vat_rate'],'order'=>(int)$li['block_order']];if(!$blocks){$blocks[10]=['type'=>'materials','title'=>'Materiales','items'=>[],'order'=>10];if((float)($q['labor_amount']??0)>0)$blocks[20]=['type'=>'labor','title'=>'Mano de obra','description'=>$q['labor_description']?:'Configuración, montaje y diseño de escenas','amount'=>(float)$q['labor_amount'],'tax_mode'=>'sin_iva','vat_rate'=>21,'order'=>20];}ksort($blocks);}
