?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=$editing?'Editar':'Nuevo'?> presupuesto · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c3{grid-column:span 3}.c4{grid-column:span 4}.c6{grid-column:span 6}.c12{grid-column:span 12}label{display:block;font-weight:650;margin-bottom:6px}input,select,textarea{width:100%;padding:10px 11px;border:1px solid #cbd1d7;border-radius:8px;font:inherit;background:#fff}.btn{border:0;border-radius:8px;padding:10px 15px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.light{background:#edf0f3;color:var(--ink)}.btn.dark{background:#242122}.btn.danger{background:#fff0ee;color:#b42318}.muted{color:var(--muted)}.flash{padding:12px 16px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.family{display:flex;gap:20px;flex-wrap:wrap}.family input{width:auto}.block{border:1px solid #dfe3e7;border-radius:12px;margin-bottom:14px;background:#fff}.block-head{display:flex;gap:10px;align-items:center;padding:13px;background:#f7f8f9;border-bottom:1px solid #e5e7ea}.block-head input{font-weight:750;font-size:16px}.block-body{padding:12px}.block-actions{display:flex;gap:6px}.block-actions button{padding:7px 9px}.suggest-wrap{position:relative;min-width:170px}.suggestions{position:absolute;z-index:50;left:0;right:0;top:100%;background:#fff;border:1px solid #cbd1d7;border-radius:8px;max-height:220px;overflow:auto;box-shadow:0 10px 24px #0002;display:none}.suggestion{padding:9px 10px;cursor:pointer}.suggestion:hover{background:#f3f5f7}.suggestion b{display:block}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #e5e7ea;vertical-align:top}th{text-align:left;font-size:12px;color:var(--muted);text-transform:uppercase}.right{text-align:right}.unit-price{width:115px}.qty{width:78px}.totals{max-width:420px;margin-left:auto}.totals div{display:flex;justify-content:space-between;padding:7px 0}.grand{font-size:20px;font-weight:800;border-top:1px solid #333;margin-top:5px;padding-top:10px!important}@media(max-width:900px){.main{margin-left:0;padding:22px}.c3,.c4,.c6{grid-column:span 12}}</style></head><body><?php erpSidebar($a);?><main class="main"><?php if($msg):?><div class="flash"><?=e8($msg)?></div><?php endif;?><div class="actions"><div style="flex:1"><h1><?=$editing?'Editar':'Nuevo'?> presupuesto</h1><p class="muted">Armá el presupuesto por sectores: materiales, mano de obra, planta baja, planta alta o como necesites.</p></div><a class="btn light" href="?a=quotes">Volver</a></div>
<form id="quoteForm" method="post" action="?a=<?=$editing?'update_quote':'save_quote'?>"><input type="hidden" name="csrf" value="<?=e8($_SESSION['csrf'])?>"><?php if($editing):?><input type="hidden" name="quote_id" value="<?=$q['id']?>"><?php endif;?><div class="card grid"><p class="c4"><label>Cliente</label><select id="client" name="client_id" required><option value="">Seleccionar</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=$preClient===(int)$c['id']?'selected':''?>><?=e8($c['business_name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Proyecto</label><select id="project" name="project_id" required><option value="">Seleccionar</option><?php foreach($projects as $p):?><option data-client="<?=$p['client_id']?>" value="<?=$p['id']?>" <?=(int)$q['project_id']===(int)$p['id']?'selected':''?>><?=e8($p['project_number'].' · '.$p['name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Versión</label><input type="number" min="1" name="version_no" value="<?=e8($q['version_no'])?>"></p><p class="c4"><label>Fecha</label><input type="date" name="quote_date" value="<?=e8($q['quote_date'])?>"></p><p class="c4"><label>Rubro</label><select name="quote_category"><?php foreach(['domotica'=>'Domótica','redes'=>'Redes','camaras'=>'Cámaras','alarma'=>'Alarma','audio'=>'Audio','general'=>'General'] as $v=>$t):?><option value="<?=$v?>" <?=$q['quote_category']===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></p><p class="c4"><label>Lista de precios</label><select id="priceList" name="price_list_id" required><?php foreach($lists as $l):?><option value="<?=$l['id']?>" <?=(int)$q['price_list_id']===(int)$l['id']?'selected':''?>><?=e8($l['name'])?> (+<?=e8($l['markup_percentage'])?>%)</option><?php endforeach;?></select></p><div class="c6"><label>Familias incluidas</label><div class="family"><?php foreach(['lifesmart'=>'LifeSmart','control4'=>'Control4','shelly'=>'Shelly'] as $v=>$t):?><label><input type="checkbox" name="quote_families[]" value="<?=$v?>" <?=in_array($v,$families,true)?'checked':''?>> <?=$t?></label><?php endforeach;?></div></div><p class="c6"><label>Plantilla principal</label><select name="quote_template_family"><?php foreach(['lifesmart'=>'LifeSmart','control4'=>'Control4','shelly'=>'Shelly'] as $v=>$t):?><option value="<?=$v?>" <?=$q['quote_template_family']===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></p></div>
<div class="card"><div class="actions"><div style="flex:1"><h2>Detalle del presupuesto</h2><p class="muted">Cada encabezado agrupa los productos que están debajo. Podés agregar varias manos de obra y cambiarles el título.</p></div><button class="btn" type="button" onclick="addMaterialBlock()">+ Encabezado / materiales</button><button class="btn dark" type="button" onclick="addLaborBlock()">+ Mano de obra</button></div><div id="blocks"><?php foreach($blocks as $b):if($b['type']==='materials'):?><div class="block material-block"><div class="block-head"><input class="block-title" value="<?=e8($b['title'])?>" placeholder="Ej.: Materiales Planta Baja"><div class="block-actions"><button type="button" class="btn light" onclick="moveBlock(this,-1)">↑</button><button type="button" class="btn light" onclick="moveBlock(this,1)">↓</button><button type="button" class="btn danger" onclick="removeBlock(this)">Eliminar</button></div></div><div class="block-body"><div style="overflow:auto"><table><thead><tr><th>SKU</th><th>Descripción</th><th>Marca</th><th>Cant.</th><th class="right">Precio USD</th><th class="right">Subtotal</th><th></th></tr></thead><tbody class="item-body"></tbody></table></div><button class="btn light" type="button" onclick="addProduct(this.closest('.material-block'))">+ Agregar producto</button></div></div><?php foreach($b['items'] as $it):?><script>window.__editRows=window.__editRows||[];window.__editRows.push(<?=json_encode(['block'=>(int)$b['order'],'product_id'=>(int)$it['product_id'],'quantity'=>(float)$it['quantity'],'unit_price'=>(float)$it['unit_price']],JSON_UNESCAPED_SLASHES)?>);</script><?php endforeach;?><?php else:?><div class="block labor-block"><div class="block-head"><input class="labor-title" value="<?=e8($b['title'])?>" placeholder="Ej.: Mano de obra Planta Baja"><div class="block-actions"><button type="button" class="btn light" onclick="moveBlock(this,-1)">↑</button><button type="button" class="btn light" onclick="moveBlock(this,1)">↓</button><button type="button" class="btn danger" onclick="removeBlock(this)">Eliminar</button></div></div><div class="block-body grid"><p class="c6"><label>Concepto</label><select class="labor-preset" onchange="applyPreset(this)"><option value="Configuración, montaje y diseño de escenas" <?=$b['description']==='Configuración, montaje y diseño de escenas'?'selected':''?>>Configuración, montaje y diseño de escenas</option><option value="Cableado, montaje y configuración" <?=$b['description']==='Cableado, montaje y configuración'?'selected':''?>>Cableado, montaje y configuración</option><option value="__manual__">Otros</option></select><input class="labor-description" style="margin-top:8px" value="<?=e8($b['description'])?>"></p><p class="c3"><label>Importe USD</label><input class="labor-amount" type="number" min="0" step=".01" value="<?=e8($b['amount'])?>" oninput="calcTotals()"></p><p class="c3"><label>IVA</label><select class="labor-tax" onchange="calcTotals()"><option value="sin_iva" <?=$b['tax_mode']==='sin_iva'?'selected':''?>>Sin IVA</option><option value="mas_iva" <?=$b['tax_mode']==='mas_iva'?'selected':''?>>+ IVA</option><option value="iva_incluido" <?=$b['tax_mode']==='iva_incluido'?'selected':''?>>IVA incluido</option></select><input class="labor-vat" type="hidden" value="<?=e8($b['vat_rate'])?>"></p></div></div><?php endif;endforeach;?></div></div>
<div class="card grid"><p class="c3"><label>IVA materiales</label><select name="materials_tax_mode" id="materialsTax" onchange="calcTotals()"><option value="mas_iva" <?=$q['materials_tax_mode']==='mas_iva'?'selected':''?>>+ IVA</option><option value="sin_iva" <?=$q['materials_tax_mode']==='sin_iva'?'selected':''?>>Sin IVA</option><option value="iva_incluido" <?=$q['materials_tax_mode']==='iva_incluido'?'selected':''?>>IVA incluido</option></select></p><p class="c3"><label>% IVA materiales</label><input id="materialsVat" type="number" step=".01" name="materials_vat_rate" value="<?=e8($q['materials_vat_rate']??21)?>" oninput="calcTotals()"></p><p class="c3"><label>Estado</label><select name="status"><?php foreach(['borrador'=>'Borrador','aprobado_inicial'=>'Aprobado inicial','final'=>'Final'] as $v=>$t):?><option value="<?=$v?>" <?=$q['status']===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></p><p class="c3"><label>&nbsp;</label><span class="muted">Materiales vienen por defecto + IVA 21%. Mano de obra, sin IVA.</span></p><p class="c12"><label>Notas generales</label><textarea name="notes"><?=e8($q['notes'])?></textarea></p><div class="c12 totals"><div><span>Materiales</span><b id="materialsTotal">US$ 0,00</b></div><div><span>Mano de obra</span><b id="laborTotal">US$ 0,00</b></div><div class="grand"><span>Total</span><b id="grandTotal">US$ 0,00</b></div></div></div><button class="btn"><?=$editing?'Guardar cambios':'Guardar presupuesto'?></button></form>
<script>
const products=<?=json_encode($productJson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,lists=<?=json_encode($listJson)?>,overrides=<?=json_encode($overrides,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,catalogPrices=<?=json_encode($catalogPrices,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let itemIndex=0,laborIndex=0;const money=n=>'US$ '+Number(n||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function productPrice(id){const p=products[id],listId=Number(document.getElementById('priceList').value),l=lists[listId];if(!p||!l)return 0;const stored=catalogPrices[id]&&catalogPrices[id][listId]!==undefined?Number(catalogPrices[id][listId]):null;if(stored!==null)return stored;const ov=overrides[id]&&overrides[id][listId]!==undefined?Number(overrides[id][listId]):null,markup=ov===null?Number(l.markup):ov;return Math.round(Number(p.cost)*(1+markup/100)*100)/100}function searchProducts(q,mode){q=String(q||'').toLowerCase().trim();let a=Object.values(products);if(q)a=a.filter(p=>String(mode==='sku'?p.sku:p.description).toLowerCase().includes(q));return a.slice(0,30)}function renderSuggestions(input,mode){const box=input.closest('.suggest-wrap').querySelector('.suggestions');box.innerHTML=searchProducts(input.value,mode).map(p=>`<div class="suggestion" data-id="${p.id}"><b>${esc(p.sku)}</b><span>${esc(p.description)}</span></div>`).join('')||'<div class="suggestion">Sin coincidencias</div>';box.style.display='block';box.querySelectorAll('[data-id]').forEach(el=>el.onmousedown=e=>{e.preventDefault();selectProduct(input.closest('tr'),el.dataset.id)})}function bindSearch(inp,mode){inp.addEventListener('input',()=>{inp.closest('tr').dataset.product='';inp.closest('tr').querySelector('.product-id').value='';renderSuggestions(inp,mode);calcTotals()});inp.addEventListener('focus',()=>renderSuggestions(inp,mode));inp.addEventListener('blur',()=>setTimeout(()=>inp.closest('.suggest-wrap').querySelector('.suggestions').style.display='none',120))}function selectProduct(tr,id,keepPrice=false){const p=products[id];if(!p)return;tr.dataset.product=id;tr.querySelector('.product-id').value=id;tr.querySelector('.sku-input').value=p.sku;tr.querySelector('.desc-input').value=p.description;tr.querySelector('.brand').textContent=p.brand;if(!keepPrice)tr.querySelector('.unit-price').value=productPrice(id).toFixed(2);tr.querySelectorAll('.suggestions').forEach(x=>x.style.display='none');calcTotals()}function addProduct(block,data=null){const i=itemIndex++,tr=document.createElement('tr');tr.innerHTML=`<td><input class="product-id" type="hidden" name="items[${i}][product_id]"><input class="section-title-hidden" type="hidden" name="items[${i}][section_title]"><input class="block-order-hidden" type="hidden" name="items[${i}][block_order]"><div class="suggest-wrap"><input class="sku-input" placeholder="Buscar SKU"><div class="suggestions"></div></div></td><td><div class="suggest-wrap"><input class="desc-input" placeholder="Buscar descripción"><div class="suggestions"></div></div></td><td class="brand">—</td><td><input class="qty" type="number" min="1" step="1" name="items[${i}][quantity]" value="${data?.quantity||1}" oninput="this.value=Math.max(1,Math.round(Number(this.value)||1));calcTotals()"></td><td class="right"><input class="unit-price" type="number" min="0" step=".01" name="items[${i}][unit_price]" value="0" oninput="calcTotals()"></td><td class="right sub">—</td><td><button class="btn danger" type="button" onclick="this.closest('tr').remove();calcTotals()">×</button></td>`;block.querySelector('.item-body').appendChild(tr);bindSearch(tr.querySelector('.sku-input'),'sku');bindSearch(tr.querySelector('.desc-input'),'desc');if(data){selectProduct(tr,String(data.product_id),true);tr.querySelector('.unit-price').value=Number(data.unit_price).toFixed(2)}calcTotals()}function blockShell(type,title){const d=document.createElement('div');d.className='block '+(type==='materials'?'material-block':'labor-block');if(type==='materials')d.innerHTML=`<div class="block-head"><input class="block-title" value="${esc(title)}"><div class="block-actions"><button type="button" class="btn light" onclick="moveBlock(this,-1)">↑</button><button type="button" class="btn light" onclick="moveBlock(this,1)">↓</button><button type="button" class="btn danger" onclick="removeBlock(this)">Eliminar</button></div></div><div class="block-body"><div style="overflow:auto"><table><thead><tr><th>SKU</th><th>Descripción</th><th>Marca</th><th>Cant.</th><th class="right">Precio USD</th><th class="right">Subtotal</th><th></th></tr></thead><tbody class="item-body"></tbody></table></div><button class="btn light" type="button" onclick="addProduct(this.closest('.material-block'))">+ Agregar producto</button></div>`;else d.innerHTML=`<div class="block-head"><input class="labor-title" value="${esc(title)}"><div class="block-actions"><button type="button" class="btn light" onclick="moveBlock(this,-1)">↑</button><button type="button" class="btn light" onclick="moveBlock(this,1)">↓</button><button type="button" class="btn danger" onclick="removeBlock(this)">Eliminar</button></div></div><div class="block-body grid"><p class="c6"><label>Concepto</label><select class="labor-preset" onchange="applyPreset(this)"><option value="Configuración, montaje y diseño de escenas">Configuración, montaje y diseño de escenas</option><option value="Cableado, montaje y configuración">Cableado, montaje y configuración</option><option value="__manual__">Otros</option></select><input class="labor-description" style="margin-top:8px" value="Configuración, montaje y diseño de escenas"></p><p class="c3"><label>Importe USD</label><input class="labor-amount" type="number" min="0" step=".01" value="0" oninput="calcTotals()"></p><p class="c3"><label>IVA</label><select class="labor-tax" onchange="calcTotals()"><option value="sin_iva">Sin IVA</option><option value="mas_iva">+ IVA</option><option value="iva_incluido">IVA incluido</option></select><input class="labor-vat" type="hidden" value="21"></p></div>`;return d}function addMaterialBlock(){const d=blockShell('materials','Materiales');document.getElementById('blocks').appendChild(d);addProduct(d);renumberBlocks()}function addLaborBlock(){document.getElementById('blocks').appendChild(blockShell('labor','Mano de obra'));renumberBlocks();calcTotals()}function moveBlock(btn,dir){const b=btn.closest('.block'),p=b.parentElement;if(dir<0&&b.previousElementSibling)p.insertBefore(b,b.previousElementSibling);if(dir>0&&b.nextElementSibling)p.insertBefore(b.nextElementSibling,b);renumberBlocks()}function removeBlock(btn){if(confirm('¿Eliminar este bloque?')){btn.closest('.block').remove();renumberBlocks();calcTotals()}}function applyPreset(sel){const inp=sel.closest('.block').querySelector('.labor-description');if(sel.value==='__manual__'){inp.focus();return}inp.value=sel.value}function renumberBlocks(){[...document.querySelectorAll('#blocks>.block')].forEach((b,i)=>{b.dataset.order=(i+1)*10;if(b.classList.contains('material-block'))b.querySelectorAll('tr').forEach(tr=>{tr.querySelector('.block-order-hidden').value=b.dataset.order;tr.querySelector('.section-title-hidden').value=b.querySelector('.block-title').value});});}function calcTotals(){let mat=0;document.querySelectorAll('.material-block tr').forEach(tr=>{const id=tr.dataset.product,qty=Number(tr.querySelector('.qty')?.value||0),price=Number(tr.querySelector('.unit-price')?.value||0),sub=id?qty*price:0;const c=tr.querySelector('.sub');if(c)c.textContent=id?money(sub):'—';mat+=sub});let labor=0,laborTaxed=0;document.querySelectorAll('.labor-block').forEach(b=>{const a=Number(b.querySelector('.labor-amount').value||0),m=b.querySelector('.labor-tax').value,v=Number(b.querySelector('.labor-vat').value||21);labor+=a;laborTaxed+=m==='mas_iva'?a*(1+v/100):a});const mm=document.getElementById('materialsTax').value,mv=Number(document.getElementById('materialsVat').value||21),matTaxed=mm==='mas_iva'?mat*(1+mv/100):mat;document.getElementById('materialsTotal').textContent=money(matTaxed);document.getElementById('laborTotal').textContent=money(laborTaxed);document.getElementById('grandTotal').textContent=money(matTaxed+laborTaxed)}function prepareSubmit(){renumberBlocks();let li=0;document.querySelectorAll('.labor-block').forEach(b=>{const order=b.dataset.order||0;[['title',b.querySelector('.labor-title').value],['description',b.querySelector('.labor-description').value],['amount',b.querySelector('.labor-amount').value],['tax_mode',b.querySelector('.labor-tax').value],['vat_rate',b.querySelector('.labor-vat').value],['block_order',order]].forEach(([k,v])=>{const inp=document.createElement('input');inp.type='hidden';inp.name=`labor_blocks[${li}][${k}]`;inp.value=v;b.appendChild(inp)});li++});document.querySelectorAll('.material-block').forEach(b=>b.querySelectorAll('tr').forEach(tr=>{tr.querySelector('.section-title-hidden').value=b.querySelector('.block-title').value;tr.querySelector('.block-order-hidden').value=b.dataset.order||0}))}document.getElementById('quoteForm').addEventListener('submit',prepareSubmit);document.getElementById('client').addEventListener('change',()=>{const c=document.getElementById('client').value,p=document.getElementById('project');[...p.options].forEach((o,i)=>{if(i===0)return;o.hidden=o.dataset.client!==c});if(p.selectedOptions[0]&&p.selectedOptions[0].hidden)p.value=''});document.getElementById('priceList').addEventListener('change',()=>{document.querySelectorAll('.material-block tr').forEach(tr=>{const id=tr.dataset.product;if(id)tr.querySelector('.unit-price').value=productPrice(id).toFixed(2)});calcTotals()});
(function init(){const c=document.getElementById('client').value,p=document.getElementById('project');[...p.options].forEach((o,i)=>{if(i===0)return;o.hidden=o.dataset.client!==c});const blocks=[...document.querySelectorAll('#blocks>.block')];const edit=window.__editRows||[];blocks.forEach((b,bi)=>{b.dataset.order=(bi+1)*10;if(b.classList.contains('material-block')){const originalOrder=<?=json_encode(array_values(array_map(static fn($b)=>(int)$b['order'],$blocks)),JSON_UNESCAPED_SLASHES)?>[bi]??b.dataset.order;const rows=edit.filter(r=>Number(r.block)===Number(originalOrder));if(rows.length)rows.forEach(r=>addProduct(b,r));else if(!<?=json_encode($editing)?>)addProduct(b);}});renumberBlocks();calcTotals()})();
</script></main></body></html>
